marker.step_source:
fmt_success = {{ _just_fmt_check.success | tojson }}
lint_success = {{ _just_lint.success | tojson }}
test_success = {{ _just_test.success | tojson }}
print(f"fmt_success={str(fmt_success).lower()}")
print(f"lint_success={str(lint_success).lower()}")
print(f"test_success={str(test_success).lower()}")
print(f"launch_fmt={str(not fmt_success).lower()}")
print(f"launch_linters={str(not lint_success).lower()}")
print(f"launch_tests={str(not test_success).lower()}")
branches = []
if not fmt_success:
    branches.append("fix_fmt")
if not lint_success:
    branches.append("fix_linters")
if not test_success:
    branches.append("fix_tests")
print(f"branches={', '.join(branches) if branches else '-'}")
if not branches:
    print("reason=all_just_checks_passed")
